mapper.select:
SELECT 
FROM yms_yard_inventory_task t
LEFT JOIN yard_zone z ON t.zone_id = z.id AND z.deleted = 0
WHERE t.deleted = 0

      AND t.warehouse_id = #{bo.warehouseId}


      AND t.inventory_no LIKE CONCAT('%', #{bo.inventoryNo}, '%')


      AND t.inventory_type = #{bo.inventoryType}


      AND t.status = #{bo.status}


      AND t.zone_id = #{bo.zoneId}

ORDER BY t.create_time DESC
